import{_ as s,o as e,c as a,a7 as d}from"./chunks/framework.B5H0CmYR.js";const g=JSON.parse('{"title":"백업","description":"","frontmatter":{"title":"백업","outline":[2,3]},"headers":[],"relativePath":"ops/backup.md","filePath":"ops/backup.md"}'),o={name:"ops/backup.md"};function i(r,t,n,l,h,c){return e(),a("div",null,[...t[0]||(t[0]=[d(`<h1 id="백업" tabindex="-1">백업 <a class="header-anchor" href="#백업" aria-label="Permalink to &quot;백업&quot;">​</a></h1><p>백업 3수단과 권장 주기, 온라인·정지 백업, 암호화, 리허설.</p><h2 id="_1-백업-수단-고르기" tabindex="-1">1. 백업 수단 고르기 <a class="header-anchor" href="#_1-백업-수단-고르기" aria-label="Permalink to &quot;1. 백업 수단 고르기&quot;">​</a></h2><p>온라인 백업 · 정지 백업 CLI · 파일시스템 스냅샷은 대체재가 아니라 역할 분담입니다. 어느 것을 언제 쓰는지부터 정합니다.</p><h3 id="_1-1-백업-3수단-—-언제-무엇을-쓰나" tabindex="-1">1-1 백업 3수단 — 언제 무엇을 쓰나 <a class="header-anchor" href="#_1-1-백업-3수단-—-언제-무엇을-쓰나" aria-label="Permalink to &quot;1-1 백업 3수단 — 언제 무엇을 쓰나&quot;">​</a></h3><p>세 수단은 서로를 대체하지 않고 역할이 나뉩니다. 온라인 백업은 서버가 떠 있어야 하므로 업그레이드 직전의 정지 백업을 대신할 수 없습니다. 정지 백업은 다운타임이 필요하므로 정기 백업에는 쓰지 않습니다.</p><p><strong>표 1-1 백업 수단 비교</strong></p><table tabindex="0"><thead><tr><th>수단</th><th>서버 상태</th><th>용도</th><th>정합 수준</th></tr></thead><tbody><tr><td><strong>온라인 백업</strong>(어드민 콘솔 내장)</td><td>기동 중</td><td>라이브 정기 백업(<strong>주 수단</strong>)</td><td>메타DB·DuckDB 상호 정합 보장(적재 일시 정지)</td></tr><tr><td><strong>정지 백업 CLI</strong>(이미지 내장)</td><td>정지</td><td>업그레이드 직전 전용</td><td>정지 상태라 파일 복사가 이미 안전</td></tr><tr><td><strong>FS 스냅샷</strong>(LVM/ZFS)</td><td>기동 중</td><td>볼륨 단위 재해복구</td><td>전원 차단 직후와 같은 상태(crash-consistent)</td></tr></tbody></table><blockquote><p><strong>참고</strong> 배포 형태가 <code>single-pg</code>(메타DB 를 PostgreSQL 에 두는 형태)여도 표 1-1 의 세 수단을 모두 쓸 수 있습니다. 온라인 백업과 정지 백업은 메타DB 를 <code>pg_dump</code> 로 뜨고, 나머지 절차(정합 유지·검증·암호화·보존)는 SQLite 와 같습니다(「백업 › 2-1 온라인 백업」). 단, 서버 이미지의 PostgreSQL 클라이언트가 있어야 하며, 조건이 맞지 않으면 제품은 사유 메시지와 함께 백업을 거부합니다. SQLite 로 운영하던 설치를 PostgreSQL 로 이관할 때(<code>./gaea.sh pg-migrate</code> — 「업그레이드 › 2-2 PG 백엔드 분기」)는 이관 <strong>전</strong>에 정지 백업을 뜨고, 이관 <strong>직후</strong> PG 백업을 새로 뜹니다. 이관 전의 SQLite 백업은 PG 배포로 복원할 수 없습니다.</p></blockquote><h3 id="_1-2-권장-주기와-보관-위치" tabindex="-1">1-2 권장 주기와 보관 위치 <a class="header-anchor" href="#_1-2-권장-주기와-보관-위치" aria-label="Permalink to &quot;1-2 권장 주기와 보관 위치&quot;">​</a></h3><p><strong>권장 주기</strong></p><ul><li><strong>온라인 백업</strong> — 기본 일 1회 (어드민 콘솔에서 상향할 수 있습니다)</li><li><strong>정지 백업</strong> — 업그레이드마다 (업그레이드 9단계의 ⑤ 단계)</li><li><strong>백업 리허설</strong> — 분기 1회 (「백업 › 2-4 백업 리허설」 · 「복구 › 1-4 RTO 리허설」)</li></ul><p>RPO 는 백업 주기로 정합니다. 기본은 일 1회이고 상향할 수 있습니다.</p><h4 id="보관-위치" tabindex="-1">보관 위치 <a class="header-anchor" href="#보관-위치" aria-label="Permalink to &quot;보관 위치&quot;">​</a></h4><table tabindex="0"><thead><tr><th>항목</th><th>내용</th></tr></thead><tbody><tr><td>기본 경로</td><td><code>&lt;GAEA_DB 디렉터리&gt;/backups</code> — 온라인 백업과 정지 백업이 함께 씁니다.</td></tr><tr><td>바꾸는 법</td><td><code>.env</code> 의 <code>GAEA_BACKUP_DIR</code> 에 절대경로를 씁니다.</td></tr><tr><td>★ 이 경로는 <strong>컨테이너 안</strong>입니다</td><td>기본값(<code>/data/backups</code>)은 도커 볼륨 <code>gaea-onprem_gaea-data</code> 안에 있어 <strong>호스트의 파일 탐색기나 <code>ls</code> 로는 보이지 않습니다.</strong> 오프사이트 복제·복구 리허설·복원 CLI 는 모두 <strong>호스트 경로</strong>를 받으므로, 먼저 볼륨에서 꺼내야 합니다(「복구 › 1-4 RTO 리허설」).</td></tr></tbody></table><p><strong>온라인 백업을 호스트로 꺼내기</strong></p><ol><li><p>백업 이름을 확인합니다(어드민 콘솔 「백업」 카드 또는 API).</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gaea.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ls</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /data/backups</span></span></code></pre></div></li><li><p>번들 디렉터리로 복사합니다. 파일 소유자가 바뀌므로 컨테이너 사용자(uid 1000)가 읽도록 맞춰 둡니다.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./backups</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gaea.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server:/data/backups/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">백업이</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">름</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./backups/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">백업이</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">름</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chown</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1000:1000</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./backups</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 안 하면 복구 리허설이 EACCES 로 멈춥니다</span></span></code></pre></div></li></ol><blockquote><p><strong>주의</strong> 기본값은 <strong>원본과 같은 디스크</strong>입니다. 운영에서는 외부 볼륨·원격 마운트를 지정하거나, 생성된 디렉터리를 오프사이트로 복제합니다.</p></blockquote><h2 id="_2-백업-실행" tabindex="-1">2. 백업 실행 <a class="header-anchor" href="#_2-백업-실행" aria-label="Permalink to &quot;2. 백업 실행&quot;">​</a></h2><p>온라인 백업은 어드민 콘솔에서, 정지 백업은 이미지 내장 CLI 로 합니다. 암호화는 선택이며, 켜면 두 경로 모두에 적용됩니다.</p><h3 id="_2-1-온라인-백업" tabindex="-1">2-1 온라인 백업 <a class="header-anchor" href="#_2-1-온라인-백업" aria-label="Permalink to &quot;2-1 온라인 백업&quot;">​</a></h3><p>운영 중에 메타DB 와 DuckDB(적재 원본)를 서로 맞는 시점으로 함께 백업합니다. 메타DB 가 SQLite 면 온라인 백업 API 로 <code>gaea.db</code> 를, <strong>PostgreSQL 이면 <code>pg_dump --format=custom</code> 으로 <code>gaea-meta.dump</code></strong> 를 뜹니다. 나머지 절차(정합 유지·검증·암호화·manifest·보존)는 같습니다. PG 는 서버 이미지의 <code>postgresql-client-16</code> 과 PG 서버의 메이저 버전이 같아야 하며, 맞지 않으면 「백업」 카드가 실행 전에 사유를 표시합니다.</p><p><strong>서버가 수행하는 시퀀스</strong></p><ol><li>적재 대기열을 일시 중지합니다.</li><li>실행 중인 적재가 끝나기를 기다립니다.</li><li>메타DB 를 뜹니다. SQLite 는 온라인 백업 API 로, PostgreSQL 은 <code>pg_dump -Fc</code> 로 뜹니다.</li><li>DuckDB 를 <code>COPY FROM DATABASE</code> 로 단일 트랜잭션에 복사합니다.</li><li>적재 대기열을 재개합니다.</li><li>백업본을 다시 열어 검증합니다.</li><li><code>manifest.json</code> 을 씁니다.</li><li>보존 정책에 따라 오래된 세대를 정리합니다.</li></ol><blockquote><p><strong>참고</strong> 조회·대시보드·공유는 백업 중에도 정상으로 동작합니다. <strong>적재만</strong> 잠깐 미뤄집니다.</p></blockquote><blockquote><p><strong>주의</strong> <strong>다중 노드 HA</strong> — 정합 창을 열 권한이 <strong>적재(extract) 리더 노드에만</strong> 있습니다. 다른 노드에서 「지금 백업」을 누르면 「다른 노드가 적재(extract) 리더입니다 — 이번 백업을 건너뜁니다」로 실패하고 부분 산출물을 남기지 않습니다. 자동 백업도 그 회차를 건너뛸 수 있으니 백업 이력에서 실제로 쌓이는지 확인합니다. 리더 노드는 <code>ha_leases</code> 의 <code>resource=&#39;extract&#39;</code> 행 <code>node_id</code> 입니다. 아카이브에는 그 노드의 DuckDB 만 담기고 <strong>공유 저장소 <code>GAEA_SNAPSHOT_DIR</code> 는 담기지 않습니다</strong> — 공유 저장소는 파일 백업으로 따로 뜹니다.</p></blockquote><h4 id="실행" tabindex="-1">실행 <a class="header-anchor" href="#실행" aria-label="Permalink to &quot;실행&quot;">​</a></h4><table tabindex="0"><thead><tr><th>항목</th><th>내용</th></tr></thead><tbody><tr><td>화면</td><td>어드민 콘솔 → <strong>「시스템 관리자」</strong> 탭 → 「백업」 카드 → <strong>지금 백업</strong></td></tr><tr><td>API</td><td><code>POST /api/admin/backup</code> — 202 로 받고, 동시 1건만 돕니다.</td></tr></tbody></table><h4 id="자동-백업-설정" tabindex="-1">자동 백업 설정 <a class="header-anchor" href="#자동-백업-설정" aria-label="Permalink to &quot;자동 백업 설정&quot;">​</a></h4><p>같은 카드의 「자동 백업 설정」에서 다섯 가지를 편집합니다.</p><ul><li>자동 주기</li><li>저장 경로</li><li>보존 세대 수</li><li>보존 총 용량 상한(GB)</li><li>정지 대기 상한(초)</li></ul><p>주기 변경은 서버를 재시작하지 않아도 다음 주기부터 반영됩니다.</p><p><strong>표 2-1 온라인 백업 산출물</strong></p><table tabindex="0"><thead><tr><th>산출물</th><th>내용</th></tr></thead><tbody><tr><td><code>gaea-backup-&lt;ISO8601&gt;/gaea.db</code></td><td>SQLite 메타(better-sqlite3 온라인 백업 API)</td></tr><tr><td><code>.../gaea-meta.dump</code></td><td>PostgreSQL 메타(<code>pg_dump --format=custom</code> — <code>gaea.db</code> 대신. 검증은 <code>pg_restore --list</code>)</td></tr><tr><td><code>.../gaea.duckdb</code></td><td>DuckDB 적재 원본(<code>COPY FROM DATABASE</code>, 별도 로그 파일 없이 단독으로 복원 가능)</td></tr><tr><td><code>.../manifest.json</code></td><td>시각 · 소요 · 파일 크기 · sha256 · 마이그레이션 헤드 · 검증 결과</td></tr><tr><td><code>.../gaea.db-wal</code>, <code>.../gaea.db-shm</code></td><td>SQLite 부속 파일. 함께 만들어집니다(<code>manifest.json</code> 의 <code>files</code> 목록과 sha256 검증 대상은 <code>gaea.db</code>·<code>gaea.duckdb</code> 둘뿐입니다). 백업을 옮길 때는 <strong>디렉터리째</strong> 옮깁니다.</td></tr></tbody></table><h3 id="_2-2-정지-백업-cli" tabindex="-1">2-2 정지 백업 CLI <a class="header-anchor" href="#_2-2-정지-백업-cli" aria-label="Permalink to &quot;2-2 정지 백업 CLI&quot;">​</a></h3><p>업그레이드 직전·이설처럼 서버를 내려야 하는 상황, 또는 제품이 뜨지 않아 어드민 콘솔에 들어갈 수 없을 때의 수단입니다.</p><p>CLI 는 <strong>런타임 이미지 안</strong>(<code>dist/scripts/backup.js</code>)에 있고, <code>./gaea.sh backup</code> 이 오버레이(jdbc·pg·ha)와 이미지 태그를 맞춰 대신 불러 줍니다. 번들만 있는 폐쇄망 호스트에서도 저장소 체크아웃 없이 동작합니다.</p><p><strong>절차</strong></p><ol><li><p>서버를 정지합니다 — <strong>정지 상태가 전제</strong>입니다(server·edge 가 떠 있으면 래퍼가 거절합니다).</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gaea.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span></span></code></pre></div></li><li><p>정지 백업을 뜹니다.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gaea.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backup</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                       # 기본 ./backups — 다른 곳: --dir &lt;디렉터리&gt;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># → ./backups/gaea-backup-&lt;타임스탬프&gt;.tar.gz[.enc]  (권한 0600)</span></span></code></pre></div></li><li><p><code>./system/restore-rehearsal.sh &lt;아카이브&gt;</code> 로 실제 복원 시간을 재 둡니다(「백업 › 2-4 백업 리허설」).</p></li></ol><table tabindex="0"><thead><tr><th>항목</th><th>내용</th></tr></thead><tbody><tr><td>PostgreSQL 메타DB</td><td>지원합니다. 번들 PG 면 래퍼가 <code>meta-postgres</code> 만 healthy 까지 올린 뒤 <code>pg_dump -Fc</code> 로 뜹니다(그 컨테이너는 「기동 중」으로 세지 않습니다). 외부 PG 는 <code>.env</code> 의 <code>GAEA_PG_URL</code> 로 붙습니다</td></tr><tr><td>권한</td><td>새로 만드는 백업 디렉터리는 0700, 아카이브는 <strong>0600</strong> 이고 실행한 계정이 소유합니다. 같은 호스트의 다른 계정은 읽을 수 없습니다</td></tr><tr><td>다중 노드</td><td><strong>전 노드를 멈춘 뒤 한 노드에서</strong> 돌립니다. 래퍼는 자기 노드의 server·edge 만 확인합니다. 공유 저장소는 담기지 않으므로 같은 창에서 따로 백업합니다</td></tr><tr><td>실패하면</td><td>원본 DB 는 건드리지 않습니다. <code>Permission denied</code> 면 <code>/data</code> 소유·권한 문제입니다</td></tr></tbody></table><blockquote><p><strong>참고</strong> 웹 운영 콘솔의 「정지 백업」 카드도 같은 명령을 실행합니다. 래퍼 없이 <code>docker compose run</code>(1.3.0 번들 루트에서는 <code>./gaea.sh compose run</code>)으로 직접 실행할 때는 래퍼와 같은 조건(<code>--user 0</code> · <code>/data</code> 읽기 전용 사본 · <code>*.duckdb.wal</code> 포함 · <code>--cap-add DAC_OVERRIDE</code>)을 그대로 지킵니다.</p></blockquote><h3 id="_2-3-백업-암호화" tabindex="-1">2-3 백업 암호화 <a class="header-anchor" href="#_2-3-백업-암호화" aria-label="Permalink to &quot;2-3 백업 암호화&quot;">​</a></h3><table tabindex="0"><thead><tr><th>항목</th><th>내용</th></tr></thead><tbody><tr><td>켜는 법</td><td><code>.env</code> 에 <code>GAEA_BACKUP_ENC_KEY</code> 를 설정합니다. <strong>설치 마법사는 값이 비어 있으면 새로 만들어 넣습니다</strong>(<code>--no-backup-enc-key</code> 로 끔 — 이미 있는 키는 지우지 않음). 업그레이드 스크립트는 키를 만들지 않으므로, 기존 설치본은 마법사를 다시 실행하기 전까지 그대로입니다.</td></tr><tr><td>키 형식</td><td>32바이트 base64 또는 64자 hex</td></tr><tr><td>적용 범위</td><td>온라인 백업과 정지 백업 CLI 양쪽. 산출물을 AES-256-GCM 스트리밍 암호화합니다(<code>.enc</code>).</td></tr><tr><td>미설정이면</td><td>평문 그대로입니다(기능은 정상). 키가 생긴 뒤의 백업부터 <code>.enc</code> 이고, 그 전의 평문 백업도 그대로 복원됩니다.</td></tr></tbody></table><h4 id="키-교체" tabindex="-1">키 교체 <a class="header-anchor" href="#키-교체" aria-label="Permalink to &quot;키 교체&quot;">​</a></h4><p><strong>절차</strong></p><ol><li><code>GAEA_BACKUP_ENC_KEY_PREVIOUS</code> 에 이전 키를 넣습니다.</li><li><code>GAEA_BACKUP_ENC_KEY</code> 를 새 키로 바꿉니다.</li></ol><p>이전 키와 새 키로 만든 백업 모두 키 지문(fingerprint)으로 맞는 키를 자동으로 골라 복원할 수 있습니다.</p><blockquote><p><strong>참고</strong> 키 원문은 로그·오류 메시지·<code>manifest</code> 어디에도 남지 않습니다. 남는 것은 8바이트 지문(fingerprint)뿐입니다.</p></blockquote><h4 id="키는-백업-매체에-들어-있지-않습니다" tabindex="-1">키는 백업 매체에 들어 있지 않습니다 <a class="header-anchor" href="#키는-백업-매체에-들어-있지-않습니다" aria-label="Permalink to &quot;키는 백업 매체에 들어 있지 않습니다&quot;">​</a></h4><p><strong>표 2-2 분실하면 되살릴 수 없는 키 2종</strong></p><table tabindex="0"><thead><tr><th>키</th><th>분실하면</th></tr></thead><tbody><tr><td><code>GAEA_BACKUP_ENC_KEY</code></td><td>암호화 백업을 되살릴 방법이 없습니다.</td></tr><tr><td><code>GAEA_DATASOURCE_CONFIG_KEY</code></td><td>데이터소스 자격증명·2FA 를 전량 재등록해야 합니다.</td></tr></tbody></table><blockquote><p><strong>경고</strong> 두 키는 백업 매체에 들어 있지 않습니다. 반드시 백업과 <strong>다른 매체에 최소 2곳</strong> 이중 보관합니다(「복구 › 2-1 사전 준비물」 사전 준비물).</p></blockquote><h4 id="보관본-만들기-—-키-복구-시트" tabindex="-1">보관본 만들기 — 키 복구 시트 <a class="header-anchor" href="#보관본-만들기-—-키-복구-시트" aria-label="Permalink to &quot;보관본 만들기 — 키 복구 시트&quot;">​</a></h4><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gaea.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keys</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                 # → gaea-recovery-keys-&lt;호스트&gt;-&lt;시각&gt;.txt (0600)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gaea.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keys</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --encrypt</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # 12자 이상 암호로 잠근 .enc</span></span></code></pre></div><p>위 두 키 + 번들 PG 비밀번호 + SSO 서명키의 값과 <strong>지문</strong>(SHA-256 앞 16자)을 담습니다. 화면에는 지문만 찍힙니다. 지문은 백업 <code>.enc</code> 헤더의 키 지문(8바이트, 16진수 16자)과 같은 규칙이라, 「이 백업을 어느 키로 풀어야 하는가」를 값 없이 대조할 수 있습니다. 파일을 서버 밖으로 옮기고 서버에서는 <code>shred -u</code> 로 지웁니다. 마법사가 키를 새로 만들었으면 설치 끝에 자동으로 만들어 경로를 알려 줍니다.</p><blockquote><p><strong>주의</strong> <strong>다중 노드는 백업 암호화 키도 전 노드가 같아야 합니다</strong> — 리더가 바뀌면 다른 노드가 백업을 만듭니다. 추가 노드는 1번 노드의 합류 꾸러미(<code>./setup.sh --export-join</code> → <code>--join</code>)로 설치해 키를 그대로 받습니다(「설치」).</p></blockquote><h3 id="_2-4-백업-리허설" tabindex="-1">2-4 백업 리허설 <a class="header-anchor" href="#_2-4-백업-리허설" aria-label="Permalink to &quot;2-4 백업 리허설&quot;">​</a></h3><p><code>system/restore-rehearsal.sh</code>(번들 루트에서 <code>./system/restore-rehearsal.sh</code>)는 운영 데이터와 운영 인스턴스를 건드리지 않습니다. 별도 임시 볼륨·포트에서 실제로 복원해 복구 시간(RTO)을 측정합니다.</p><table tabindex="0"><thead><tr><th>항목</th><th>내용</th></tr></thead><tbody><tr><td>권장 주기</td><td><strong>분기 1회</strong></td></tr><tr><td>상세 절차</td><td>「복구 › 1-4 RTO 리허설」 RTO 리허설에 명령과 측정 기준값이 있습니다.</td></tr><tr><td>실패하면</td><td>「일상 운영 › 3-2 흔한 증상과 조치」로 갑니다.</td></tr></tbody></table><blockquote><p><strong>참고</strong> 복원해 보지 않은 백업은 장애 때 실제로 복원된다는 보장이 없습니다.</p></blockquote>`,60)])])}const k=s(o,[["render",i]]);export{g as __pageData,k as default};
